import { z } from "zod"

/**
 * MCP Server Use Types
 */
export interface McpServerUse {
	type: string
	serverName: string
	toolName?: string
	uri?: string
}

/**
 * McpExecutionStatus
 */

export const mcpExecutionStatusSchema = z.discriminatedUnion("status", [
	z.object({
		executionId: z.string(),
		status: z.literal("started"),
		serverName: z.string(),
		toolName: z.string(),
	}),
	z.object({
		executionId: z.string(),
		status: z.literal("output"),
		response: z.string(),
	}),
	z.object({
		executionId: z.string(),
		status: z.literal("completed"),
		response: z.string().optional(),
	}),
	z.object({
		executionId: z.string(),
		status: z.literal("error"),
		error: z.string().optional(),
	}),
])

export type McpExecutionStatus = z.infer<typeof mcpExecutionStatusSchema>

// ibm_change_start
/**
 * MCP Server Connection Status Types
 *
 * These types define the structure of status messages sent from the backend
 * to the frontend when MCP servers connect, disconnect, or encounter errors.
 */

/**
 * Status of an MCP server connection
 */
export type McpServerConnectionStatus = "connecting" | "connected" | "disconnected" | "error"

/**
 * Message sent to webview when an MCP server's connection status changes
 */
export interface McpServerStatusMessage {
	/** The name/ID of the MCP server */
	serverName: string
	
	/** Current connection status */
	status: McpServerConnectionStatus
	
	/** Source of the server configuration (global or project-level) */
	source: "global" | "project"
	
	/** Error message if status is "error" or "disconnected" with an error */
	error?: string
	
	/** Timestamp when the status changed */
	timestamp: number
}
// ibm_change_end
