// ============================================================================
// Command execution types
// ============================================================================

/**
 * Zod schema for command execution details.
 * Based on ``ExitCodeDetails`` from ``src/integrations/terminal/types.ts``
 */
const exitCodeDetails = z.object({
	exitCode: z.number().optional(),
	signal: z.number().optional(),
	signalName: z.string().optional(),
	coreDumpPossible: z.boolean().optional(),
})

/**
 * Details about the exit status of a command execution.
 */
export type ExitCodeDetails = z.infer<typeof exitCodeDetails>

/**
 * Zod schema for the result of a command or code execution.
 */
const commandResult = z.object({
	command: z.string().optional(),
	stdout: z.string().optional(),
	stderr: z.string().optional(),
	error: z.instanceof(Error).optional(),
	details: exitCodeDetails.optional(),
})

/**
 * The result of executing a command, including output, errors, and exit details.
 */
export type CommandResult = z.infer<typeof commandResult>

/**
 * Represents the execution status of a step-like entity in the modernization workflow.
 */
export enum StepLikeStatus {
	PENDING = "pending",
	RUNNING = "running",
	SUCCESS = "success",
	FAILURE = "failure",
	ERROR = "error",
	SKIPPED = "skipped",
	CANCELLED = "cancelled",
}

/**
 * Zod schema for the result of a step-like entity execution.
 */
const _stepLikeResult = z.object({
	status: z.nativeEnum(StepLikeStatus),
	/** The result of the step execution (command and/or other logic) */
	executionResult: commandResult.optional(),
	/** Additional data associated with the step result */
	data: z.any().optional(),
})

/**
 * The result of executing a step-like entity, including status, command/code results, and additional data.
 */
export type StepLikeResult = z.infer<typeof _stepLikeResult>

/**
 * Zod schema for a step-like entity in the modernization workflow.
 */
const _stepLike = z.object({
	id: z.string(),
	name: z.string(),
	description: z.string(),
	status: z.nativeEnum(StepLikeStatus),
	result: _stepLikeResult.optional(),
	required: z.boolean().optional(),
	fixable: z.boolean().optional(),
})

/**
 * Represents a step-like entity in the Java modernization workflow with its metadata, status, and results.
 * Used as a common interface for blocks of logic that should report the current execution status.
 */
export type StepLike = z.infer<typeof _stepLike>

